package io.github.nanoforged.adpters.janino.impl.delegate;

import net.minecraft.launchwrapper.LaunchClassLoader;

import java.lang.reflect.Field;
import java.security.ProtectionDomain;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import java.util.Objects;

/**
 * Supplies generated bytecode to a LaunchClassLoader before using its normal transformation path.
 * The target loader owns class identity, transformer execution and protection-domain selection.
 */
public class LCLDelegate extends ClassloaderAdpter {
    private final LaunchClassLoader launchClassLoader;
    private final Map<String, byte[]> resourceCache;

    /**
     * Creates a delegate and resolves the target loader's resource cache once.
     *
     * @param classLoader the loader that will transform and define generated classes
     * @throws NullPointerException if the loader is null
     * @throws IllegalStateException if its resource cache cannot be accessed
     */
    public LCLDelegate(LaunchClassLoader classLoader) {
        super(Objects.requireNonNull(classLoader, "classLoader"));
        this.launchClassLoader = classLoader;
        this.resourceCache = resourceCache(classLoader);
    }

    /**
     * Publishes an owned copy of the byte range under the dotted binary name, then loads the class.
     * A prior resource miss is cleared so it cannot hide the newly supplied bytecode. This does not
     * clear the loader's invalid-class cache or redefine already loaded classes. Names must not be
     * redirected by loader/transformer exclusions or remapped to a different resource name.
     *
     * @param name the dotted binary name
     * @param b the untransformed class bytes
     * @param off the first byte to publish
     * @param len the number of bytes to publish
     * @param protectionDomain ignored; the target loader chooses the protection domain
     * @return the class returned by the target loader after its normal loading pipeline
     * @throws ClassNotFoundException if the target loader cannot load the class
     * @throws NullPointerException if the name or bytes are null
     * @throws IndexOutOfBoundsException if the byte range is invalid
     */
    @Override
    public Class<?> defineClasses(String name, byte[] b, int off, int len,
                                  ProtectionDomain protectionDomain) throws ClassNotFoundException {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(b, "b");
        Objects.checkFromIndexSize(off, len, b.length);
        resourceCache.put(name, Arrays.copyOfRange(b, off, off + len));
        launchClassLoader.clearNegativeEntries(Collections.singleton(name));
        return launchClassLoader.loadClass(name);
    }

    /** Resolves the field on the declaring class, including when the target is a subclass. */
    @SuppressWarnings("unchecked")
    private static Map<String, byte[]> resourceCache(LaunchClassLoader loader) {
        try {
            Field field = LaunchClassLoader.class.getDeclaredField("resourceCache");
            field.setAccessible(true);
            return (Map<String, byte[]>) Objects.requireNonNull(field.get(loader), "resourceCache");
        } catch (ReflectiveOperationException | RuntimeException ex) {
            throw new IllegalStateException("Cannot access LaunchClassLoader.resourceCache", ex);
        }
    }
}
